begin
                 Print(15,'       이 길을 통과하고자하는 사람은');
                 Print(15,'     양측의 늪속에 있는 레버를 당기시오');
              end

begin
              Clear;
              if y = 46 then
              if wantexit then begin
                 with party do begin
                    xaxis := 48; yaxis := 58; map := 4;
                 end;
                 load; scroll(TRUE);
              end
              else begin
                 dec(y); scroll(TRUE);
              end;
              if on(11,40) then begin
                 if party.etc[3] > 0 then begin
                    Print(7,' 늪 아래를 보니 무언가 반짝이는 물체가 있었');
                    Print(7,'다. 하지만 늪위를 걷는 마법 때문에 늪속으로');
                    Print(7,'들어갈수가 없다.');
                    PressAnyKey;
                 end
                 else begin
                    Print(7,' 일행은 독을 무릅쓰고  늪속에 빠져있는 레버');
                    Print(7,'를 당겼다. 순간 동굴 중심부에서 굉음이 들렸');
                    Print(7,'다.');
                    PressAnyKey;
                    map[11,40] := 49;
                    map[41,39] := 0;
                 end;
              end;
              if on(41,39) then begin
                 if party.etc[3] > 0 then begin
                    Print(7,' 늪 아래를 보니 무언가 반짝이는 물체가 있었');
                    Print(7,'다. 하지만 늪위를 걷는 마법 때문에 늪속으로');
                    Print(7,'들어갈수가 없다.');
                    PressAnyKey;
                 end
                 else begin
                    Print(7,' 일행은 독을 무릅쓰고  늪속에 빠져있는 레버');
                    Print(7,'를 당겼다. 순간 동굴 중심부에서 조금전 보다');
                    Print(7,'더 큰 굉음이 들렸다.');
                    PressAnyKey;
                    map[41,39] := 49;
                    if not odd(party.etc[40]) then begin
                       for j := 27 to 36 do begin
                          map[24,j] := 25;
                          map[28,j] := 23;
                       end;
                       map[24,37] := 17; map[28,37] := 19;
                       for j := 27 to 37 do
                       for i := 25 to 27 do map[i,j] := 44;
                       party.etc[40] := (random(7)+1) shl 1;
                    end;
                 end;
              end;
              if (y in [8..12]) and not odd(party.etc[40]) then begin
                 enemynumber := random(3) + 3;
                 for i := 1 to enemynumber do begin
                    joinenemy(i,59);
                    with enemy[i] do begin
                       E_number := 25;
                       hp := 210;
                       level := 7;
                    end;
                 end;
                 DisplayEnemies(TRUE);
                 BattleMode(TRUE);
                 map[x,y] := 49;
              end;
              if (y = 6) and not odd(party.etc[40]) then begin
                 map[x,y-1] := 49;
                 Silent_Scroll;
                 j := party.etc[40] shr 1;
                 if j <> (x-10) div 4 then begin
                    Print(7,' 여기에는 봉인이 발견되지 않았다');
                    map[x,y] := 49;
                    PressAnyKey;
                 end
                 else begin
                    enemynumber := 7;
                    for i := 1 to 3 do joinenemy(i,59);
                    for i := 4 to enemynumber do begin
                       joinenemy(i,59);
                       with enemy[i] do begin
                          E_number := 25;
                          hp := 210;
                          level := 7;
                       end;
                    end;
                    DisplayEnemies(TRUE);
                    Print(13,'나는 EVIL GOD의 봉인을 지키고 있는 CRAB GOD');
                    Print(13,'의 왕이다. CRAB GOD 족의 명예를 걸고 절대로');
                    Print(13,'너희 같은 자들에게 봉인을 넘겨주지 않겠다!!');
                    PressAnyKey;
                    BattleMode(FALSE);
                    if party.etc[6] = 255 then exit;
                    Clear;
                    if party.etc[6] = 0 then begin
                       Print(15,' 당신은 이 동굴에 보관되어 있는 봉인을 발견');
                       Print(15,'했다.  그리고는 봉쇄 되었던 봉인을 풀어버렸');
                       Print(15,'다.');
                       party.etc[40] := party.etc[40] or bit1;
                       PressAnyKey;
                    end
                    else begin
                       inc(y);
                       scroll(TRUE);
                    end;
                 end;
              end;
           end
